class Solution:
    def combinationSum(self, candidates: list[int], target: int) -> list[list[int]]:
        ans = []
        path = []

        def choose(start: int, remaining: int) -> None:
            if remaining < 0:
                return

            if remaining == 0:
                ans.append(path[:])
                return

            for i in range(start, len(candidates)):
                path.append(candidates[i])
                choose(i, remaining - candidates[i])
                path.pop()

        choose(0, target)
        return ans
